42	interface TimelineItem {
43		id: string;
44		at: number;
45		title: string;
46		body?: string | null;
47		unread?: boolean;
48		href?: string | null;
49		/** The specific run this item represents (for peek pane deep-link). */
50		runId?: number | null;
51		notification?: NotificationItem;
52		/** Approval run id when this is an action_approval_needed card. */
53		approvalRunId?: number | null;
54		/** Kind of pending interaction behind the card ('approval' today). */
55		interactionType?: string | null;
56		/** Live interaction state from its authoritative per-type source. */
57		interactionStatus?: string | null;
58		/** Server policy: this interaction can be completed inline from the feed. */
59		interactionInline?: boolean;
60		/** Named outcomes for a one-click decision, and the field they answer. */
61		interactionChoiceField?: string | null;
62		interactionChoices?: Array<{ value: string; label: string }> | null;
63		notificationId?: number | null;
64	}
