66	/** Navigate preserving query strings (TanStack `to: full?query` drops `?…`). */
67	function useOpenAppHref() {
68		const navigate = useNavigate();
69		return (href: string) => {
70			const { pathname, search } = parseAppHref(href);
71			void navigate({
72				to: pathname as "/",
73				search: (search ?? {}) as never,
74			});
75		};
76	}
77	
78	/** Link that accepts a full app-relative href including query. */
79	function AppHrefLink({
80		href,
81		className,
82		onClick,
83		children,
84	}: {
85		href: string;
86		className?: string;
87		onClick?: (e: React.MouseEvent) => void;
88		children: ReactNode;
89	}) {
90		const { pathname, search } = parseAppHref(href);
91		return (
92			<Link
93				to={pathname as "/"}
94				search={(search ?? {}) as never}
95				className={className}
96				onClick={onClick}
97			>
98				{children}
99			</Link>
100		);
101	}
102	
103	function notificationIcon(type: string, isRead: boolean) {
104		if (!isRead) {
105			return <span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-blue-500" />;
106		}
107		const iconClass = "mt-0.5 h-4 w-4 shrink-0 text-muted-foreground";
108		switch (type) {
109			case "action_approval_needed":
110				return <GitPullRequest className={iconClass} />;
111			case "connection_permission_request":
112			case "browser_auth_expired":
113				return <Link2 className={iconClass} />;
114			case "invitation_received":
115				return <Mail className={iconClass} />;
116			case "agent_message":
117				return <Bot className={iconClass} />;
118			default:
119				return <Bell className={iconClass} />;
120		}
121	}
122	
123	function kindLabel(notificationType?: string): string {
124		return notificationType
125			? notificationKindLabel(notificationType)
126			: "Notification";
127	}
