129	function ApprovalActions({
130		runId,
131		notificationId,
132		reviewHref,
133		reviewTitle,
134		choiceField,
135		choices,
136		onSettled,
137	}: {
138		runId: number;
139		notificationId: number;
140		/** Deep-link to Memory ActionApprovalCard (schema form). */
141		reviewHref?: string | null;
142		/** Pane header title when the CTA opens the peek pane. */
143		reviewTitle?: string;
144		/**
145		 * A decision with named outcomes rather than approve/reject: one button per
146		 * option, each approving with `{ [choiceField]: value }`. Approve/Reject
147		 * cannot stand in — the schema REQUIRES this field, so a bare approve would
148		 * record an empty answer while reporting success.
149		 */
150		choiceField?: string | null;
151		choices?: Array<{ value: string; label: string }> | null;
152		onSettled?: () => void;
153	}) {
154		const { orgContext } = useOrgContext();
155		const approveRun = useApproveRun();
156		const rejectRun = useRejectRun();
157		const markRead = useMarkNotificationRead(orgContext);
158		const queryClient = useQueryClient();
159		const peek = useNotificationPeek();
160		const [resolved, setResolved] = useState<"approved" | "rejected" | null>(
161			null,
162		);
163		const [showReject, setShowReject] = useState(false);
164		const [reason, setReason] = useState("");
165		const busy = approveRun.isPending || rejectRun.isPending;
166	
167		const invalidate = () => {
168			void queryClient.invalidateQueries({ queryKey: ["activity-feed"] });
169			void queryClient.invalidateQueries({ queryKey: ["recent-runs"] });
170			void queryClient.invalidateQueries({ queryKey: ["notifications"] });
171			void queryClient.invalidateQueries({
172				queryKey: ["notifications-unread-count"],
173			});
174			onSettled?.();
175		};
176	
177		if (resolved === "approved") {
178			return (
179				<p className="mt-2 text-xs font-medium text-emerald-600 dark:text-emerald-400">
180					Approved — executing…
181				</p>
182			);
183		}
184		if (resolved === "rejected") {
185			return (
186				<p className="mt-2 text-xs font-medium text-muted-foreground">Rejected</p>
187			);
188		}
189	
190		if (showReject) {
191			return (
192				<div className="mt-2 flex flex-wrap items-center gap-2">
193					<input
194						type="text"
195						placeholder="Reason (optional)"
196						value={reason}
197						onChange={(e) => setReason(e.target.value)}
198						className="h-7 min-w-[10rem] flex-1 rounded-md border bg-background px-2 text-xs"
199						onClick={(e) => e.stopPropagation()}
200					/>
201					<Button
202						size="sm"
203						variant="outline"
204						className="h-7 text-xs"
205						disabled={busy}
206						onClick={(e) => {
207							e.stopPropagation();
208							rejectRun.mutate(
209								{ run_id: runId, reason: reason.trim() || undefined },
210								{
211									onSuccess: () => {
212										setResolved("rejected");
213										markRead.mutate(notificationId);
214										invalidate();
215									},
216								},
217							);
218						}}
219					>
220						{rejectRun.isPending ? (
221							<Spinner size="sm" className="mr-1" />
222						) : (
223							<X className="mr-1 h-3 w-3" />
224						)}
225						Reject
226					</Button>
227					<button
228						type="button"
229						className="text-xs text-muted-foreground hover:text-foreground"
230						onClick={(e) => {
231							e.stopPropagation();
232							setShowReject(false);
233						}}
234					>
235						Cancel
236					</button>
237				</div>
238			);
239		}
240	
241		// Named outcomes replace approve/reject entirely — mixing them would offer a
242		// bare "Approve" that answers none of the options the question asked.
243		if (choiceField && choices && choices.length > 0) {
244			return (
245				<div className="mt-2 flex flex-wrap items-center gap-2">
246					{choices.map((choice) => (
247						<Button
248							key={choice.value}
249							size="sm"
250							variant="outline"
251							className="h-7 text-xs"
252							disabled={busy}
253							onClick={(e) => {
254								e.stopPropagation();
255								approveRun.mutate(
256									{ run_id: runId, input: { [choiceField]: choice.value } },
257									{
258										onSuccess: () => {
259											setResolved("approved");
260											markRead.mutate(notificationId);
261											invalidate();
262										},
263									},
264								);
265							}}
266						>
267							{approveRun.isPending ? (
268								<Spinner size="sm" className="mr-1" />
269							) : null}
270							{choice.label}
271						</Button>
272					))}
273					<Button
274						size="sm"
275						variant="ghost"
276						className="h-7 text-xs text-muted-foreground"
277						disabled={busy}
278						onClick={(e) => {
279							e.stopPropagation();
280							setShowReject(true);
281						}}
282					>
283						<X className="mr-1 h-3 w-3" />
284						Dismiss
285					</Button>
286				</div>
287			);
288		}
289	
290		return (
291			<div className="mt-2 flex flex-wrap items-center gap-2">
292				{reviewHref ? (
293					// Peek is the default destination — the detail is a preview, not a
294					// context switch. The pane carries a destination link for the cases
295					// that want the real route. Falls back to navigation when the
296					// href isn't previewable or no provider is mounted.
297					peek && parsePeekHref(reviewHref) ? (
298						<Button
299							type="button"
300							size="sm"
301							variant="outline"
302							className="h-7 text-xs"
303							onClick={(e) => {
304								e.stopPropagation();
305								markRead.mutate(notificationId);
306								peek.open({
307									href: reviewHref,
308									title: reviewTitle ?? "Approval",
309									runId,
310								});
311							}}
312						>
313							Review
314						</Button>
315					) : (
316						<AppHrefLink
317							href={reviewHref}
318							className={cn(
319								"inline-flex h-7 items-center justify-center rounded-md border border-input bg-background px-3 text-xs font-medium shadow-xs transition-colors hover:bg-accent hover:text-accent-foreground",
320							)}
321							onClick={(e) => {
322								e.stopPropagation();
323								markRead.mutate(notificationId);
324							}}
325						>
326							Review
327						</AppHrefLink>
328					)
329				) : null}
330				<Button
331					size="sm"
332					className="h-7 text-xs"
333					disabled={busy}
334					onClick={(e) => {
335						e.stopPropagation();
336						approveRun.mutate(
337							{ run_id: runId },
338							{
339								onSuccess: () => {
340									setResolved("approved");
341									markRead.mutate(notificationId);
342									invalidate();
343								},
344							},
345						);
346					}}
347				>
348					{approveRun.isPending ? (
349						<Spinner size="sm" className="mr-1" />
350					) : (
351						<Check className="mr-1 h-3 w-3" />
352					)}
353					Approve
354				</Button>
355				<Button
356					size="sm"
357					variant="outline"
358					className="h-7 text-xs"
359					disabled={busy}
360					onClick={(e) => {
361						e.stopPropagation();
362						setShowReject(true);
363					}}
364				>
365					<X className="mr-1 h-3 w-3" />
366					Reject
367				</Button>
368			</div>
369		);
370	}
