372	/** Shared attention-inbox state: the unread/pending items plus the bulk
373	 *  read/approve/reject actions over exactly what is visible. The Activity
374	 *  page's "Needs attention" lens renders it as a bulk bar (tab row) + list. */
375	export function useAttentionInbox(owner: string | null) {
376		const { session } = useAuthState();
377		const { orgContext } = useOrgContext();
378		const markManyRead = useMarkNotificationsRead(orgContext);
379		const bulkDecision = useBulkRunDecision();
380	
381		const {
382			data: cards = [],
383			isLoading,
384			isError,
385		} = useActivityFeed(session && owner ? owner : null, {
386			limit: 50,
387			aggregate: true,
388			includeNotifications: true,
389			includeRuns: false,
390			kinds: ["notification"],
391		});
392	
393		// Server returns the collapsed feed oldest→newest (that order is what its
394		// adjacent-collapse pass needs). The attention list reads top-down, so the
395		// display list flips to newest-first; every other consumer of the items
396		// (bulk-bar sets, sidebar counts) is order-insensitive.
397		const items = useMemo((): TimelineItem[] => {
398			return cards
399				.map((c) => {
400					const isApproval = c.status === "action_approval_needed";
401					return {
402						id: c.id,
403						at: new Date(c.at).getTime(),
404						title: c.title,
405						body: c.body,
406						unread: c.unread,
407						href: c.href,
408						runId: c.run_id ?? null,
409						approvalRunId: isApproval ? (c.run_id ?? null) : null,
410						interactionType: isApproval ? (c.interaction_type ?? null) : null,
411						interactionStatus: isApproval
412							? (c.interaction_status ?? null)
413							: null,
414						interactionInline: isApproval
415							? (c.interaction_inline ?? false)
416							: false,
417						interactionChoiceField: isApproval
418							? (c.interaction_choice_field ?? null)
419							: null,
420						interactionChoices: isApproval
421							? (c.interaction_choices ?? null)
422							: null,
423						notificationId: c.notification_id ?? null,
424						// Synthetic NotificationItem for approval actions / mark-read
425						notification:
426							c.notification_id != null
427								? ({
428										id: c.notification_id,
429										type: c.status ?? "generic",
430										title: c.title,
431										body: c.body,
432										resource_url: c.href,
433										resource_type: c.run_id != null ? "run" : null,
434										resource_id: c.run_id != null ? String(c.run_id) : null,
435										is_read: !c.unread,
436										created_at: c.at,
437										organization_id: "",
438										user_id: "",
439									} satisfies NotificationItem)
440								: undefined,
441					};
442				})
443				.reverse();
444		}, [cards]);
445		/** Raw feed cards behind `attentionItems` — keeps attribution fields
446		 *  (`behavior_id`, MCP href params) for row-level badge matching. */
447		const attentionCards = useMemo(
448			() =>
449				cards.filter(
450					(card) =>
451						card.unread ||
452						(card.status === "action_approval_needed" &&
453							card.interaction_status === "pending"),
454				),
455			[cards],
456		);
457	
458		const attentionItems = useMemo(
459			() =>
460				items.filter(
461					(item) => item.unread || item.interactionStatus === "pending",
462				),
463			[items],
464		);
465		const visibleUnreadIds = [
466			...new Set(
467				attentionItems.flatMap((item) =>
468					item.unread && item.notificationId != null ? [item.notificationId] : [],
469				),
470			),
471		];
472		const visibleApprovals = attentionItems.filter(
473			(item) =>
474				item.interactionType === "approval" &&
475				item.interactionStatus === "pending" &&
476				item.interactionInline === true &&
477				item.approvalRunId != null,
478		);
479		const visibleApprovalRunIds = [
480			...new Set(
481				visibleApprovals.flatMap((item) =>
482					item.approvalRunId != null ? [item.approvalRunId] : [],
483				),
484			),
485		];
486	
487		const markVisibleRead = async () => {
488			const result = await markManyRead.mutateAsync(visibleUnreadIds);
489			if (result.failed > 0) {
490				toast.error(
491					`Marked ${result.succeeded} read; ${result.failed} could not be updated.`,
492				);
493			} else {
494				toast.success(
495					`Marked ${result.succeeded} notification${result.succeeded === 1 ? "" : "s"} as read.`,
496				);
497			}
498		};
499	
500		const decideVisibleApprovals = async (
501			decision: "approve" | "reject",
502			reason?: string,
503		) => {
504			const result = await bulkDecision.mutateAsync({
505				decision,
506				runIds: visibleApprovalRunIds,
507				...(reason ? { reason } : {}),
508			});
509			const failed = new Set(result.failedRunIds);
510			const decidedNotificationIds = visibleApprovals.flatMap((item) =>
511				item.approvalRunId != null &&
512				!failed.has(item.approvalRunId) &&
513				item.notificationId != null
514					? [item.notificationId]
515					: [],
516			);
517			if (decidedNotificationIds.length > 0) {
518				await markManyRead.mutateAsync(decidedNotificationIds);
519			}
520			if (result.failed > 0) {
521				toast.error(
522					`${result.succeeded} ${decision === "approve" ? "approved" : "rejected"}; ${result.failed} failed.`,
523				);
524			} else {
525				toast.success(
526					`${result.succeeded} approval${result.succeeded === 1 ? "" : "s"} ${decision === "approve" ? "approved" : "rejected"}.`,
527				);
528			}
529		};
530	
531		const bulkPending = bulkDecision.isPending || markManyRead.isPending;
532	
533		return {
534			session,
535			isLoading,
536			isError,
537			attentionCards,
538			attentionItems,
539			visibleUnreadIds,
540			visibleApprovalRunIds,
541			markVisibleRead,
542			decideVisibleApprovals,
543			markManyRead,
544			bulkPending,
545		};
546	}
