548	/** Bulk actions for the visible attention items — rendered on the Activity
549	 *  page's lens tab row, right-aligned. Hidden when there is nothing to do. */
550	export function AttentionBulkBar({ owner }: { owner: string }) {
551		const {
552			session,
553			isLoading,
554			attentionItems,
555			visibleUnreadIds,
556			visibleApprovalRunIds,
557			markVisibleRead,
558			decideVisibleApprovals,
559			bulkPending,
560		} = useAttentionInbox(owner);
561		const [showBulkReject, setShowBulkReject] = useState(false);
562		const [bulkRejectReason, setBulkRejectReason] = useState("");
563	
564		if (
565			!session ||
566			isLoading ||
567			attentionItems.length === 0 ||
568			(visibleUnreadIds.length === 0 && visibleApprovalRunIds.length === 0)
569		) {
570			return null;
571		}
572	
573		return (
574			<div className="flex flex-wrap items-center justify-end gap-2">
575				{visibleUnreadIds.length > 0 ? (
576					<Button
577						type="button"
578						variant="outline"
579						size="sm"
580						className="h-7 rounded-md bg-muted text-xs"
581						disabled={bulkPending}
582						onClick={() => void markVisibleRead()}
583					>
584						<CheckCheck className="h-3.5 w-3.5" />
585						Mark {visibleUnreadIds.length} as read
586					</Button>
587				) : null}
588				{visibleApprovalRunIds.length > 0 ? (
589					<>
590						<Button
591							type="button"
592							size="sm"
593							className="h-7 rounded-md text-xs"
594							disabled={bulkPending}
595							onClick={() => void decideVisibleApprovals("approve")}
596						>
597							<Check className="h-3.5 w-3.5" />
598							Approve {visibleApprovalRunIds.length}
599						</Button>
600						<Button
601							type="button"
602							variant="outline"
603							size="sm"
604							className="h-7 rounded-md bg-muted text-xs"
605							disabled={bulkPending}
606							onClick={() => setShowBulkReject(true)}
607						>
608							<X className="h-3.5 w-3.5" />
609							Reject {visibleApprovalRunIds.length}
610						</Button>
611					</>
612				) : null}
613	
614				{showBulkReject ? (
615					<div className="flex w-full flex-wrap items-center gap-2 rounded-md bg-muted/40 p-2">
616						<input
617							type="text"
618							aria-label="Reject reason"
619							placeholder="Reason (optional)"
620							value={bulkRejectReason}
621							onChange={(event) => setBulkRejectReason(event.target.value)}
622							className="h-7 min-w-48 flex-1 rounded-md border bg-background px-2 text-xs"
623						/>
624						<Button
625							type="button"
626							variant="destructive"
627							size="sm"
628							className="h-7 rounded-md text-xs"
629							disabled={bulkPending}
630							onClick={() => {
631								void decideVisibleApprovals(
632									"reject",
633									bulkRejectReason.trim() || undefined,
634								);
635								setShowBulkReject(false);
636								setBulkRejectReason("");
637							}}
638						>
639							Confirm reject {visibleApprovalRunIds.length}
640						</Button>
641						<Button
642							type="button"
643							variant="ghost"
644							size="sm"
645							className="h-7 text-xs"
646							onClick={() => setShowBulkReject(false)}
647						>
648							Cancel
649						</Button>
650					</div>
651				) : null}
652			</div>
653		);
654	}
