656	/** The attention list itself: unread/pending rows with inline actions, peek,
657	 *  and ↑↓/Enter/R keyboard navigation. */
658	export function AttentionList({
659		owner,
660		emptyState = null,
661	}: {
662		owner: string;
663		/** Shown when nothing needs attention (the Activity lens empty state). */
664		emptyState?: ReactNode;
665	}) {
666		const openHref = useOpenAppHref();
667		const peek = useNotificationPeek();
668		const { orgContext } = useOrgContext();
669		const markRead = useMarkNotificationRead(orgContext);
670		const {
671			session,
672			isLoading,
673			isError,
674			attentionItems,
675			markManyRead,
676		} = useAttentionInbox(owner);
677		const [activeIndex, setActiveIndex] = useState(0);
678		const attentionRef = useRef<HTMLElement>(null);
679	
680		const openItem = (item: TimelineItem) => {
681			if (item.notificationId != null && item.unread) {
682				markRead.mutate(item.notificationId);
683			}
684			// Prefer the right-side peek pane when the item is previewable and a
685			// provider is present (workspace surfaces). Event/run targets are URL-backed;
686			// generic notifications keep their complete row snapshot local because the
687			// API has no exact notification read. The explicit CTA still opens full page.
688			if (peek) {
689				peek.open({
690					href: item.href ?? "",
691					title: item.title,
692					runId: item.runId ?? undefined,
693					body: item.body,
694					notificationType: item.notification?.type,
695					createdAt: item.notification?.created_at,
696				});
697				return;
698			}
699			if (item.href) openHref(item.href);
700		};
701	
702		const focusAttentionItem = (index: number) => {
703			const nextIndex = Math.min(Math.max(index, 0), attentionItems.length - 1);
704			setActiveIndex(nextIndex);
705			attentionRef.current
706				?.querySelector<HTMLElement>(`[data-attention-index="${nextIndex}"]`)
707				?.focus();
708		};
709	
710		if (!session) {
711			return (
712				<p className="py-6 text-center text-sm text-muted-foreground">
713					Sign in to see workspace activity.
714				</p>
715			);
716		}
717	
718		if (isLoading && attentionItems.length === 0) {
719			return (
720				<div className="space-y-2">
721					{Array.from({ length: 4 }).map((_, i) => (
722						<div
723							// biome-ignore lint/suspicious/noArrayIndexKey: static skeleton
724							key={i}
725							className={cn(FILLED_BOX, "h-14 animate-pulse")}
726						/>
727					))}
728				</div>
729			);
730		}
731	
732		if (isError) {
733			return (
734				<p className="py-6 text-center text-sm text-destructive">
735					Could not load recent activity.
736				</p>
737			);
738		}
739	
740		if (attentionItems.length === 0) {
741			return emptyState;
742		}
743	
744		const list = (
745			<ul className="space-y-1">
746				{attentionItems.map((item, itemIndex) => {
747					const approvalRunId = item.approvalRunId ?? null;
748					// Gate action UI on the card's interaction kind — the generic
749					// contract — not the notification type. A future interaction kind
750					// adds its own branch here without changing the card shape.
751					const isApprovalInteraction = item.interactionType === "approval";
752					// interaction_status is NOT a fixed enum (contract: treat any value
753					// not explicitly handled as non-actionable). Every resolved
754					// non-pending status renders as a neutral outcome chip — an unknown
755					// value like 'auto' must never fall through to an actionable CTA.
756					const approvalOutcome = isApprovalInteraction
757						? item.interactionStatus === "approved"
758							? "Approved"
759							: item.interactionStatus === "rejected"
760								? "Rejected"
761								: item.interactionStatus === "expired"
762									? "Expired"
763									: item.interactionStatus && item.interactionStatus !== "pending"
764										? item.interactionStatus.charAt(0).toUpperCase() +
765											item.interactionStatus.slice(1)
766										: null
767						: null;
768					const showInlineApproval =
769						isApprovalInteraction &&
770						item.interactionStatus === "pending" &&
771						item.interactionInline === true &&
772						approvalRunId != null;
773					const actionLabel =
774						!showInlineApproval && !approvalOutcome && item.notification
775							? notificationActionLabel(item.notification.type, item.href)
776							: null;
777					const itemKindLabel =
778						isApprovalInteraction && approvalOutcome
779							? "Approval"
780							: kindLabel(item.notification?.type);
781	
782					const summaryText = notificationSummaryMarkdown(item.body);
783					const rowClass = cn(
784						FILLED_BOX,
785						"flex w-full items-start gap-3 p-3 text-left transition-colors",
786						"hover:bg-accent/50",
787					);
788					const icon = item.notification
789						? notificationIcon(item.notification.type, !item.unread)
790						: notificationIcon("generic", !item.unread);
791	
792					const body = (
793						<>
794							{icon}
795							<div className="min-w-0 flex-1">
796								<div className="flex items-baseline gap-2">
797									<p
798										className={cn(
799											"min-w-0 flex-1 truncate text-sm",
800											item.unread
801												? "font-medium text-foreground"
802												: "text-foreground/90",
803										)}
804									>
805										{item.title}
806									</p>
807									<span className="shrink-0 text-[11px] text-muted-foreground">
808										{formatTimeAgo(item.at)}
809									</span>
810								</div>
811								{summaryText ? (
812									// Summary only — the detail list and review link live in the
813									// focused/peek view. Links inside stop propagation so they
814									// don't also trigger the row's open-peek handler.
815									// biome-ignore lint/a11y/noStaticElementInteractions: wrapper only stops bubbling from nested links
816									// biome-ignore lint/a11y/useKeyWithClickEvents: no own behaviour; the row handles keyboard
817									<div
818										className="mt-0.5 line-clamp-2 text-xs text-muted-foreground"
819										onClick={(e) => {
820											if ((e.target as HTMLElement).closest("a")) {
821												e.stopPropagation();
822											}
823										}}
824									>
825										<InlineMarkdownText
826											text={summaryText}
827											// Approval bodies are server-composed and carry our own
828											// entity permalinks, so same-origin anchors survive; the
829											// renderer drops external ones either way. Every other type
830											// — above all agent_message, whose body an agent supplies
831											// verbatim — renders link text with no anchor at all.
832											linkPolicy={
833												item.notification?.type === "action_approval_needed"
834													? "app-links"
835													: "strip"
836											}
837										/>
838									</div>
839								) : item.body ? (
840									<p className="mt-0.5 line-clamp-2 text-xs text-muted-foreground">
841										{item.body}
842									</p>
843								) : null}
844								<p className="mt-1 text-[10px] font-medium uppercase tracking-wide text-muted-foreground/80">
845									{itemKindLabel}
846								</p>
847								{showInlineApproval &&
848								item.notification &&
849								approvalRunId != null ? (
850									<ApprovalActions
851										runId={approvalRunId}
852										notificationId={item.notification.id}
853										reviewHref={item.href}
854										reviewTitle={item.title}
855										choiceField={item.interactionChoiceField}
856										choices={item.interactionChoices}
857									/>
858								) : approvalOutcome ? (
859									<p
860										className={cn(
861											"mt-2 text-xs font-medium",
862											item.interactionStatus === "approved"
863												? "text-emerald-600 dark:text-emerald-400"
864												: "text-muted-foreground",
865										)}
866									>
867										{approvalOutcome}
868									</p>
869								) : null}
870								{actionLabel && item.href ? (
871									<div className="mt-2">
872										<AppHrefLink
873											href={item.href}
874											className="inline-flex h-7 items-center justify-center rounded-md border border-input bg-background px-3 text-xs font-medium shadow-xs transition-colors hover:bg-accent hover:text-accent-foreground"
875											onClick={(e) => {
876												e.stopPropagation();
877												if (item.notification && !item.notification.is_read) {
878													markRead.mutate(item.notification.id);
879												}
880												if (
881													item.notification?.type === "action_approval_needed" &&
882													peek &&
883													parsePeekHref(item.href ?? "")
884												) {
885													e.preventDefault();
886													openItem(item);
887												}
888											}}
889										>
890											{actionLabel}
891										</AppHrefLink>
892									</div>
893								) : null}
894							</div>
895						</>
896					);
897	
898					// Div (not <button>/<a>) so nested Review/Reconnect links are valid HTML.
899					return (
900						<li key={item.id}>
901							{/* biome-ignore lint/a11y/useSemanticElements: a real anchor cannot contain the notification's nested action links */}
902							<div
903								data-attention-index={itemIndex}
904								role="link"
905								tabIndex={0}
906								onFocus={() => setActiveIndex(itemIndex)}
907								onClick={() => openItem(item)}
908								onKeyDown={(e) => {
909									if (e.target !== e.currentTarget) return;
910									if (e.key === "Enter" || e.key === " ") {
911										e.preventDefault();
912										openItem(item);
913									}
914								}}
915								className={cn(rowClass, "cursor-pointer")}
916							>
917								{body}
918							</div>
919						</li>
920					);
921				})}
922			</ul>
923		);
924	
925		return (
926			<section
927				ref={attentionRef}
928				data-attention-list
929				aria-label="Needs attention"
930				aria-keyshortcuts="ArrowDown ArrowUp Enter R"
931				className="space-y-2.5"
932				onKeyDown={(event) => {
933					const target = event.target as HTMLElement;
934					if (
935						target.matches("input, textarea, select") ||
936						target.isContentEditable
937					) {
938						return;
939					}
940					if (event.key === "ArrowDown" || event.key === "ArrowUp") {
941						const focusedRow = target.closest<HTMLElement>(
942							"[data-attention-index]",
943						);
944						if (!focusedRow) return;
945						event.preventDefault();
946						const focusedIndex = Number(focusedRow?.dataset.attentionIndex);
947						const startingIndex = Number.isInteger(focusedIndex)
948							? focusedIndex
949							: event.key === "ArrowDown"
950								? -1
951								: 0;
952						focusAttentionItem(
953							startingIndex + (event.key === "ArrowDown" ? 1 : -1),
954						);
955					}
956					if (event.key.toLowerCase() === "r") {
957						const active = attentionItems[activeIndex];
958						if (active?.unread && active.notificationId != null) {
959							event.preventDefault();
960							void markManyRead.mutateAsync([active.notificationId]);
961						}
962					}
963				}}
964			>
965				{list}
966				<div
967					data-testid="attention-shortcut-hint"
968					role="note"
969					aria-label="Attention keyboard shortcuts"
970					className="attention-shortcut-hint pointer-events-none mx-auto mt-3 w-fit items-center gap-4 rounded-full border bg-background/95 px-5 py-2 text-xs text-muted-foreground shadow-lg backdrop-blur"
971				>
972					<span>
973						<kbd className="rounded bg-muted px-1.5 py-0.5">↑↓</kbd> Navigate
974					</span>
975					<span>
976						<kbd className="rounded bg-muted px-1.5 py-0.5">Enter</kbd> Open
977					</span>
978					<span>
979						<kbd className="rounded bg-muted px-1.5 py-0.5">R</kbd> Mark read
980					</span>
981					<span>
982						<kbd className="rounded bg-muted px-1.5 py-0.5">Tab</kbd> Actions
983					</span>
984				</div>
985			</section>
986		);
