54	/**
55	 * Activity surface product strip: one line linking to the behavior's durable
56	 * outputs. Ownership/corrections live on the entity page; this surface is for
57	 * automation health + runs.
58	 */
59	export function BehaviorOutputsStrip({
60		owner,
61		behaviorId,
62		organizationId,
63	}: {
64		owner: string;
65		behaviorId: string;
66		organizationId: string;
67	}) {
68		const { data: promoted, isLoading } = useBehaviorPromotedEntities(
69			behaviorId,
70			organizationId,
71		);
72		const resultCount = promoted?.length ?? 0;
73		const hasMore = resultCount > PROMOTED_DISPLAY_LIMIT;
74		const count = Math.min(resultCount, PROMOTED_DISPLAY_LIMIT);
75		// Label/link by the OBSERVED output types, never the current keying_config:
76		// after an output-type change the historical rows span types, and a
77		// config-derived label would count all of them while linking to only the
78		// newest type's subset. An overflowed fetch is only a sample — it cannot
79		// prove the unfetched tail shares the type, so stay generic then too.
80		const promotedTypes = new Set(
81			promoted?.map((entity) => entity.entity_type).filter(Boolean) ?? [],
82		);
83		const entityType =
84			!hasMore && promotedTypes.size === 1 ? [...promotedTypes][0] : null;
85	
86		if (isLoading) {
87			return <Skeleton className="h-10 w-full rounded-lg" />;
88		}
89		if (count === 0) return null;
90	
91		const displayCount = hasMore ? `${PROMOTED_DISPLAY_LIMIT}+` : String(count);
92		const label =
93			entityType != null
94				? `${displayCount} ${entityType} ${count === 1 ? "entity" : "entities"} built by this behavior`
95				: `${displayCount} ${count === 1 ? "entity" : "entities"} built by this behavior`;
96	
97		const memoryLink =
98			entityType != null
99				? memoryBrowseTypeSearch(owner, entityType)
100				: {
101						to: "/$owner/memory" as const,
102						params: { owner },
103						search: {},
104					};
105	
106		return (
107			<div
108				className={cn(
109					FILLED_BOX,
110					"flex flex-wrap items-center justify-between gap-2 px-3 py-2.5 text-sm",
111				)}
112			>
113				<span className="text-muted-foreground">{label}</span>
114				<Button asChild variant="ghost" size="sm" className="h-7 gap-1">
115					<Link
116						to={memoryLink.to}
117						params={memoryLink.params}
118						search={memoryLink.search}
119					>
120						View in Memory
121						<ArrowRight className="h-3.5 w-3.5" />
122					</Link>
123				</Button>
124			</div>
125		);
126	}
