176	/** Edit an existing behavior — the behavior's edit form. Reuses the same
177	 *  builder as create (in its `editingBehavior` mode: pre-filled, saves as a new
178	 *  version). Prefills the version-owned config (classifiers / reactions_guidance
179	 *  / keying_config) so a save round-trips them instead of clobbering.
180	 *
181	 *  When `runId` is set (Slack config-approval deep link) AND the behavior has an
182	 *  agent, this is a REVIEW of a held builder proposal: {@link ProposalReviewShell}
183	 *  owns the fetch + fail-closed review lifecycle + Approve/Reject; the render-prop
184	 *  shows a current→proposed DIFF while the review is active, and the editable form
185	 *  otherwise. Fail-closed — a loading/errored proposal never exposes the editable
186	 *  form; only an explicit "gone" (404, run resolved/absent) restores normal
187	 *  editing. Agentless behaviors have no builder proposals, so they edit directly. */
188	function BehaviorDefinitionPane({
189		agentId,
190		behaviorId,
191		runId,
192		organizationId,
193		onDone,
194	}: {
195		agentId: string | null;
196		behaviorId: string;
197		runId?: number;
198		organizationId: string;
199		onDone: () => void;
200	}) {
201		const [triggersDraft, setTriggersDraft] = useState<BehaviorTriggersDraft>({
202			ready: false,
203			triggers: [],
204		});
205		const handleTriggersChange = useCallback((draft: BehaviorTriggersDraft) => {
206			setTriggersDraft((prev) =>
207				JSON.stringify(prev) === JSON.stringify(draft) ? prev : draft,
208			);
209		}, []);
210		const detail = useBehaviorDetail(behaviorId, undefined, organizationId, {
211			includeVersions: true,
212		});
213		const w = detail.data?.behavior;
214	
215		const skeleton = (
216			<div className="flex flex-col gap-4">
217				{[0, 1, 2].map((i) => (
218					<Skeleton key={i} className="h-16 w-full rounded-lg" />
219				))}
220			</div>
221		);
222	
223		const editForm = detail.isLoading ? (
224			skeleton
225		) : w ? (
226			<CreateBehaviorForm
227				organizationId={organizationId}
228				prefillAgentId={agentId ?? undefined}
229				editingBehavior={{
230					behavior_id: w.behavior_id,
231					name: w.behavior_name,
232					slug: w.slug,
233					description: w.description,
234					prompt: w.prompt,
235					sources: w.sources,
236					reaction_script: w.reaction_script,
237					agent_id: w.agent_id,
238					device_worker_id: w.device_worker_id,
239					agent_kind: w.agent_kind,
240					classifiers: w.classifiers,
241					keying_config: w.keying_config,
242					reactions_guidance: w.reactions_guidance,
243					triggers: w.triggers,
244				}}
245				createFields={{
246					// Full array from the multi-trigger editor — never collapse to [0].
247					triggers: triggersDraft.triggers,
248				}}
249				triggerFields={
250					<BehaviorTriggersEditor
251						key={JSON.stringify(w.triggers ?? [])}
252						organizationId={organizationId}
253						initialTriggers={w.triggers ?? []}
254						onChange={handleTriggersChange}
255					/>
256				}
257				hideHeader
258				hideCancel
259				submitDisabled={!triggersDraft.ready}
260				onClose={onDone}
261				onSuccess={onDone}
262			/>
263		) : (
264			<p className="text-sm text-muted-foreground">
265				Behavior not found. It may have been removed.
266			</p>
267		);
268	
269		// No agent → no builder proposals to review; the deep link just edits.
270		if (!agentId) return editForm;
271	
272		return (
273			<ProposalReviewShell
274				resource={{ kind: "behavior", agentId, behaviorId: behaviorId }}
275				runId={runId}
276				onDone={onDone}
277			>
278				{({ reviewMode, proposal }) =>
279					reviewMode === "active" ? (
280						// A manage_behaviors update is a PATCH. The server computes
281						// `proposedAfter` (the STORED values, via the same normalizer the
282						// apply handler uses), so the "after" is just `current` overlaid with
283						// it — displayed == applied, no client-side coercion.
284						<JsonDiff
285							before={proposal?.current ?? null}
286							after={{
287								...(proposal?.current ?? {}),
288								...(proposal?.proposedAfter ?? {}),
289							}}
290						/>
291					) : reviewMode === "loading" ? (
292						skeleton
293					) : reviewMode === "error" ? null : (
294						editForm
295					)
296				}
297			</ProposalReviewShell>
298		);
299	}
