import { Link, useNavigate } from "@tanstack/react-router";
import { ArrowLeft, Bot, Pencil } from "lucide-react";
import {
	type BehaviorView,
	BehaviorDetailContent,
} from "@/components/behaviors/behavior-detail-content";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useOrgContext } from "@/hooks/use-org-context";
import { useBehaviorDetail } from "@/hooks/use-behaviors";
import { useResolvedPath } from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";

/**
 * Workspace-level Behavior detail — the single home for every behavior,
 * agent-owned and agentless alike. `activity` (default) shows the outputs
 * strip plus the run thread (agent-owned) or the activity-stream link
 * (agentless); `definition` shows the edit form with an UNLOCKED agent
 * picker, so a behavior can gain, swap, or drop its executor here. A
 * `run_id` opens the held builder proposal review for agent-owned behaviors.
 */
export function WorkspaceBehaviorRoute({
	owner,
	behaviorId,
	view,
	runId,
}: {
	owner: string;
	behaviorId: string;
	view: BehaviorView;
	runId?: number;
}) {
	const navigate = useNavigate();
	const { orgContext, hasOrgContext } = useOrgContext();
	const { data: resolvedData, isLoading: isResolvedLoading } = useResolvedPath(
		`/${owner}`,
		orgContext,
	);
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const organizationId = resolvedData?.workspace?.id ?? "";
	const isLoading = isAuthenticated
		? !hasOrgContext || isResolvedLoading || isOrgLoading
		: isResolvedLoading || isOrgLoading;
	void isMember;

	const detail = useBehaviorDetail(behaviorId, undefined, organizationId);
	const record = detail.data?.behavior;
	const behaviorName = record?.behavior_name ?? "Behavior";

	const backToList = () =>
		void navigate({ to: "/$owner/behaviors", params: { owner } });
	const toActivity = () =>
		void navigate({
			to: "/$owner/behaviors/$behaviorId",
			params: { owner, behaviorId },
			search: { view: "activity", run_id: undefined },
		});
	// Editing = the `definition` view. A runId is a config-approval review, which
	// owns its own Approve/Reject lifecycle — no Edit toggle there.
	const isEditing = !runId && view === "definition";

	return (
		<div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
			<div className="mx-auto flex w-full min-w-0 max-w-3xl flex-col gap-4">
				<div className="flex flex-wrap items-center justify-between gap-3">
					<div className="flex min-w-0 items-center gap-2">
						<Button
							type="button"
							variant="ghost"
							size="sm"
							className="h-8 gap-1.5 text-muted-foreground hover:text-foreground"
							onClick={backToList}
						>
							<ArrowLeft className="h-3.5 w-3.5" />
							Behaviors
						</Button>
						<h1 className="flex min-w-0 items-center gap-2 truncate font-display text-xl font-semibold">
							<Bot className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
							{isLoading && !record ? (
								<Skeleton className="h-5 w-40" />
							) : runId ? (
								"Review change"
							) : (
								behaviorName
							)}
						</h1>
					</div>
					{runId ? null : isEditing ? (
						<Button
							type="button"
							variant="ghost"
							size="sm"
							className="h-8 text-muted-foreground hover:text-foreground"
							onClick={toActivity}
						>
							Done
						</Button>
					) : (
						<Button asChild variant="ghost" size="sm" className="h-8 gap-1.5">
							<Link
								to="/$owner/behaviors/$behaviorId"
								params={{ owner, behaviorId }}
								search={{ view: "definition", run_id: undefined }}
							>
								<Pencil className="h-3.5 w-3.5" />
								Edit
							</Link>
						</Button>
					)}
				</div>

				<BehaviorDetailContent
					owner={owner}
					agentId={record?.agent_id ?? null}
					behaviorId={behaviorId}
					view={view}
					runId={runId}
					onDone={runId ? backToList : toActivity}
				/>
			</div>
		</div>
	);
}

