387	export type MemoryResource =
388	  | { kind: 'run'; runId: number }
389	  | { kind: 'behavior_run'; runId: number; agentId: string; behaviorId: number }
390	  | { kind: 'event'; eventId: number }
391	  | { kind: 'feed'; feedId: number };
