397	      return `run_ids=${resource.runId}`;
398	    case 'behavior_run':
399	      return `agent=${encodeURIComponent(resource.agentId)}&behavior=${resource.behaviorId}&run_ids=${resource.runId}`;
400	    case 'event':
401	      return `content_ids=${resource.eventId}`;
402	    case 'feed':
403	      return `feed_ids=${resource.feedId}`;
404	  }
