import { useCallback, useMemo } from "react";
import { AgentChatPanelSkeleton } from "@/components/agents/agent-loading-shells";
import { AgentThread } from "@/components/agents/agent-thread";
import {
	type ChatMessage,
	historyInteractionsToMessage,
	ReadOnlyChatProvider,
	serverRowToMessage,
} from "@/components/agents/lobu-chat-store";
import { useNotificationPeek } from "@/components/peek/notification-peek-context";
import {
	trustedBehaviorInteractionArgs,
	useBehaviorEntityResolutionInteractions,
} from "@/components/behaviors/entity-resolution-interactions";
import { stitchRunThreads } from "@/components/behaviors/behavior-thread-stitch";
import { useBehaviorRunThreads } from "@/lib/api/agents";
import { buildEntityUrl } from "@/lib/url";

/** The Behavior dispatch harness sends a long internal "Run this Behavior now…
 *  Required steps:" prompt as the first user turn. That's plumbing, not content
 *  — drop it so the read-only thread shows the agent's work + output only. */
const DISPATCH_PROMPT = /(?:^|\n)Run this Behavior now/;

export function isDispatchScaffold(message: ChatMessage): boolean {
	return (
		message.role === "user" &&
		message.parts.some((p) => p.type === "text" && DISPATCH_PROMPT.test(p.text))
	);
}

export function behaviorInteractionMessageId(interaction: {
	runId: number;
	eventId?: number;
}): string {
	return `history-interaction:${interaction.runId}:${interaction.eventId ?? "error"}`;
}

/**
 * A behavior's completed runs rendered as ONE read-only conversation: each
 * scheduled run is a separated bot turn-sequence (its tool calls + output).
 * No composer — the agent worked on its own.
 */
export function BehaviorRunThread({
	agentId,
	behaviorId,
	ownerSlug,
	runId,
}: {
	agentId: string;
	behaviorId: string;
	ownerSlug: string;
	/** When set, show only this single run's transcript (used by the peek pane). */
	runId?: number;
}) {
	const { data, isLoading } = useBehaviorRunThreads(agentId, behaviorId, {
		orgSlug: ownerSlug,
	});
	const interactionExtension = useBehaviorEntityResolutionInteractions();
	const peek = useNotificationPeek();
	// Clicking a run separator opens just that run in the peek pane. Only offered
	// in the full multi-run thread (not when this thread IS a single-run peek) and
	// only where a peek provider is mounted (the workspace layout).
	const onRunSelect = useCallback(
		(clickedRunId: number) => {
			peek?.open({
				href: `/${ownerSlug}/behaviors/${behaviorId}?run_id=${clickedRunId}`,
				title: `Behavior run #${clickedRunId}`,
				runId: clickedRunId,
			});
		},
		[peek, ownerSlug, agentId, behaviorId],
	);

	const messages = useMemo(() => {
		const runs = data?.runs ?? [];
		const filtered =
			runId != null ? runs.filter((r) => r.runId === runId) : runs;
		// API returns newest-first; a thread reads oldest → newest.
		const ordered = filtered.slice().reverse();
		return stitchRunThreads(
			ordered.map((run) => {
				const runMessages: ChatMessage[] = run.messages
					.map((row) => serverRowToMessage(row, { showToolCalls: true }))
					.filter(
						(m): m is ChatMessage => m !== null && !isDispatchScaffold(m),
					);
				if (run.task?.trim()) {
					runMessages.unshift({
						id: "task",
						role: "user",
						parts: [{ type: "text", text: run.task.trim() }],
					});
				}
				for (const automatic of run.automaticActions ?? []) {
					const entityHref = (entity: typeof automatic.loser) =>
						buildEntityUrl(ownerSlug, [
							...(entity.parentEntityType && entity.parentSlug
								? [
										{
											entity_type: entity.parentEntityType,
											slug: entity.parentSlug,
										},
									]
								: []),
							{ entity_type: entity.entityType, slug: entity.slug },
						]);
					runMessages.push({
						id: `automatic-action:${automatic.operationId}`,
						role: "assistant",
						parts: [
							{
								type: "tool-call",
								toolCallId: `automatic-action-${automatic.operationId}`,
								toolName: "entity-merge-result",
								args: trustedBehaviorInteractionArgs({
									...automatic,
									loserHref: entityHref(automatic.loser),
									winnerHref: entityHref(automatic.winner),
								}),
							},
						],
					});
				}
				const actions = run.actions ?? [];
				const pendingActions = actions.filter(
					(action) => action.status === "pending",
				);
				if (pendingActions.length > 1) {
					const windowId = pendingActions[0]?.windowId ?? null;
					const runIds = pendingActions
						.map((action) => action.runId)
						.sort((left, right) => left - right);
					runMessages.push({
						id: "approval-batch",
						role: "assistant",
						parts: [
							{
								type: "tool-call",
								toolCallId: `approval-batch-${run.runId}`,
								toolName: "behavior-approval-batch",

			interaction_status: c.req.query("interaction_status") || undefined,
			entity_types: parseStringListParam(c.req.query("entity_types")),
		};

		const ctx = toToolContext(extractAuthContext(c));
		const result = await getContent(params as any, c.env, ctx);
		return c.json(toJsonSafe(result));
	} catch (error) {
		logger.error({ error }, "[REST API] Knowledge search error");
		return c.json({ error: errorMessage(error) }, 400);
	}
}

export async function publicRestSearchKnowledge(c: Context<{ Bindings: Env }>) {
	return withPublicOrg(c, async (organizationId) => {
		const query = c.req.query("query");

		const connectionId = safeParseInt(c.req.query("connection_id"), { min: 1 });
		const contentIds = c.req.query("content_ids");
		const params = {
			query: query?.trim() || undefined,
			entity_id: safeParseInt(c.req.query("entity_id"), { min: 1 }),
			connection_ids:
				parseIdListParam(c.req.query("connection_ids")) ??
				(connectionId ? [connectionId] : undefined),
			feed_ids: parseIdListParam(c.req.query("feed_ids")),
			run_ids: parseIdListParam(c.req.query("run_ids")),
			platforms: parsePlatformsQuery(
				c.req.query("platforms"),
				c.req.query("platform")
			),
			since: c.req.query("since"),
			until: c.req.query("until"),
			engagement_min: safeParseInt(c.req.query("engagement_min"), {
				min: 0,
				max: 100,
			}),
			engagement_max: safeParseInt(c.req.query("engagement_max"), {
				min: 0,
				max: 100,
			}),
			classification_filters: (() => {
				const raw = c.req.query("classification_filters");
				if (!raw) return undefined;
				try {
					return JSON.parse(raw);
				} catch {
					return undefined;
				}
			})(),
			classification_source: c.req.query("classification_source") || undefined,
			window_id: safeParseInt(c.req.query("window_id"), { min: 1 }),
			content_ids: contentIds
				? contentIds
						.split(",")
						.map((id) => safeParseInt(id.trim(), { min: 1 }))
						.filter((id): id is number => id !== undefined)
				: undefined,
			min_similarity: safeParseFloat(c.req.query("min_similarity"), {
				min: 0,
				max: 1,
			}),
			include_classification:
				c.req.query("include_classification") || undefined,
			limit: safeParseInt(c.req.query("limit"), { min: 1, max: 500 }),
			offset: safeParseInt(c.req.query("offset"), { min: 0 }),
			sort_by: c.req.query("sort_by") || undefined,
			sort_order: c.req.query("sort_order") || undefined,
			before_occurred_at: c.req.query("before_occurred_at") || undefined,
			before_id: safeParseInt(c.req.query("before_id"), { min: 1 }),
			after_occurred_at: c.req.query("after_occurred_at") || undefined,
			after_id: safeParseInt(c.req.query("after_id"), { min: 1 }),
			interaction_status: c.req.query("interaction_status") || undefined,
			entity_types: parseStringListParam(c.req.query("entity_types")),
		};

		return getContent(
			params as any,
			c.env,
			publicToolContext(c.req.url, organizationId)
		);

		evidence: Array<{ kind: string; identifier: string }>;
		appliedAt: string;
	}>;
}

export interface BehaviorRunThreadHistory {
	runs: BehaviorRunThreadItem[];
}

/** A behavior's recent completed runs, newest-first, as raw transcripts. The
 *  caller stitches them into one read-only thread. */
export function useBehaviorRunThreads(
	agentId?: string | null,
	behaviorId?: string | number | null,
	options?: { enabled?: boolean; orgSlug?: string | null; limit?: number },
) {
	const { slug } = getPathScope();
	const orgSlug = options?.orgSlug ?? slug;
	const limit = options?.limit ?? 20;

	return useQuery({
		queryKey: ["behavior-run-threads", orgSlug, agentId, behaviorId, limit],
		queryFn: async (): Promise<BehaviorRunThreadHistory> => {
			const res = await fetchWithTimeout(
				agentHistoryUrl(
					agentId ?? "",
					`/behaviors/${behaviorId}/thread?limit=${limit}`,
				),
				{ credentials: "include", headers: orgScopedHeaders(orgSlug) },
			);
			if (res.status === 401 || res.status === 403) {
				return { runs: [] };
			}
			await throwIfNotOk(res, "Failed to fetch Behavior runs");
			const data = (await res.json()) as Partial<BehaviorRunThreadHistory>;
			return {
				runs: Array.isArray(data.runs) ? data.runs : [],
			};
		},
		enabled:
			!!orgSlug && !!agentId && !!behaviorId && (options?.enabled ?? true),
		staleTime: 5_000,
	});
}

export function useAgentConfig(
	agentId?: string | null,
	options?: { enabled?: boolean },
) {
	const { slug } = getPathScope();

	return useQuery({
		queryKey: ["agent-config", slug, agentId],
		queryFn: async (): Promise<AgentSettings> => {
			const res = await fetchWithTimeout(
				agentsUrl(slug!, `/${agentId}/config`),
				{
					credentials: "include",
				},
			);
			await throwIfNotOk(res, "Failed to fetch agent config");

	app.get("/behaviors/:behaviorId/thread", async (c) => {
		const scope = await getAuthorizedAgentScope(c);
		if (!scope) return errorResponse(c, "Unauthorized", 401);
		if (!scope.organizationId) return c.json({ runs: [] });

		const watcherId = Number(c.req.param("behaviorId"));
		if (!Number.isFinite(watcherId)) {
			return errorResponse(c, "Invalid behavior id", 400);
		}
		const limit = Math.min(parseInt(c.req.query("limit") || "20", 10), 50);

		const data = await readWatcherRunThreads({
			agentId: scope.agentId,
			watcherId,
			organizationId: scope.organizationId,
			limit,
		});
		if (artifactStore && publicGatewayUrl) {
			for (const run of data.runs) {
				run.messages = run.messages.map((message) =>
					message.role === "user"
						? {
								...message,
								content: resignFileRefs(
									message.content,
									artifactStore,
									publicGatewayUrl
								),
							}
						: message
				);
			}
		}
		return c.json(data);
	});

	app.get("/status", async (c) => {
		const scope = await getAuthorizedAgentScope(c);
		if (!scope) return errorResponse(c, "Unauthorized", 401);

		const { connected, resolvedAgentId } = await resolveActiveAgent(
			scope.agentId
		);

		let hasSessionFile =
			(await readLatestSnapshotJsonl(resolvedAgentId, scope.organizationId)) !==
			null;
		if (!hasSessionFile) {
			hasSessionFile = !!(await findSessionFile(resolvedAgentId));
		}

		return c.json({
			connected: connected || hasSessionFile,
			hasHttpServer: !!connectionManager?.getHttpUrl(resolvedAgentId),
			deploymentCount: connectionManager
				? connectionManager.getDeploymentsForAgent(resolvedAgentId).length
				: 0,
		});
	});

	app.get("/session/messages", async (c) => {
		const scope = await getAuthorizedAgentScope(c);
		if (!scope) return errorResponse(c, "Unauthorized", 401);

		const cursor = c.req.query("cursor") || "";
		const limit = Math.min(parseInt(c.req.query("limit") || "50", 10), 200);

		const result = await proxyOrFallback(
			scope.agentId,
			`/session/messages?cursor=${cursor}&limit=${limit}`,
			(resolved) =>
				readSessionMessages(resolved, cursor, limit, scope.organizationId)
		);

		if (!result) {
			return c.json(
				{
					error: "Agent offline",
					connected: false,
					messages: [],
					nextCursor: null,
					hasMore: false,
				},
				503
			);
		}

		return c.json(result.data);
	});

	app.get("/session/stats", async (c) => {
		const scope = await getAuthorizedAgentScope(c);
		if (!scope) return errorResponse(c, "Unauthorized", 401);

		const result = await proxyOrFallback(
			scope.agentId,
			"/session/stats",
			(resolved) => readSessionStats(resolved, scope.organizationId)
		);

		if (!result) {
			return c.json({ error: "Agent offline", connected: false }, 503);
		}

		return c.json(result.data);
	});

	return app;
}

