  // A raw tweet/LinkedIn post has no title, so interleaving them made this
  // notification open a list of untitled body text — "random tweets" — with the
  // actual ranked output buried among them. Each signal already carries
  // source_url and parent_event_id, so the source stays one hop away.
  const contentIds = deliveredSignals.map((signal) => signal.id);`;

