/**
 * Seed the workspace Activity feed locally so the "random tweets" fix is
 * directly testable.
 *
 * Copies the 10 REAL events behind prod notification 4858497 (5 raw source
 * tweets/posts with EMPTY titles, 5 ranked signal observations with titles)
 * into burak-emre-kabakci, then emits TWO notifications over the same run:
 *   BEFORE — content_ids interleaves each signal with its source row (what the
 *            reaction script used to build; opens as a list of untitled tweets)
 *   AFTER  — content_ids lists only the ranked signals (what it builds now)
 * Click both from Activity to see the difference.
 */
import postgres from "postgres";

const SCRATCH =
	"/private/tmp/claude-501/-Users-burakemre-Code-lobu/caf26cd6-7152-465a-818d-0afdf6a9b617/scratchpad";
const ORG_SLUG = "burak-emre-kabakci";
const USER_ID = "AePvkODil8AuKFDK66MZp2PiupofU9an";

const sql = postgres(process.env.DATABASE_URL!, { ssl: false, onnotice: () => {} });

const prodEvents: Array<Record<string, any>> = JSON.parse(
	await Bun.file(`${SCRATCH}/prod-events.json`).text(),
);

const [org] = await sql`SELECT id FROM organization WHERE slug = ${ORG_SLUG}`;
const orgId = org.id as string;

// The behavior + run seeded earlier, so the cards attribute to something real.
const [beh] = await sql`
  SELECT id FROM watchers
  WHERE organization_id = ${orgId} AND slug = 'social-interest-radar-local-repro'`;
const [run] = await sql`
  SELECT id FROM runs
  WHERE organization_id = ${orgId} AND watcher_id = ${beh.id} AND run_type = 'behavior'
  ORDER BY id DESC LIMIT 1`;

// Idempotent: drop anything a previous run of this script left behind.
await sql`DELETE FROM notification_targets WHERE event_id IN (
  SELECT id FROM events WHERE organization_id = ${orgId} AND origin_id LIKE 'localseed:%')`;
await sql`DELETE FROM events WHERE organization_id = ${orgId} AND origin_id LIKE 'localseed:%'`;

const idMap = new Map<number, number>();
for (const e of prodEvents) {
	const [row] = await sql`
    INSERT INTO events
      (organization_id, origin_id, title, payload_type, payload_text, source_url,
       occurred_at, metadata, semantic_type, origin_type, connector_key, feed_key,
       run_id, created_by, entity_ids)
    VALUES
      (${orgId}, ${`localseed:${e.origin_id}`}, ${e.title}, ${e.payload_type},
       ${e.payload_text}, ${e.source_url}, ${e.occurred_at},
       ${sql.json(e.metadata ?? {})}, ${e.semantic_type}, ${e.origin_type},
       ${e.connector_key}, ${e.feed_key}, ${run.id}, ${USER_ID}, '{}')
    RETURNING id`;
	idMap.set(Number(e.id), Number(row.id));
}

const sourceIds = prodEvents
	.filter((e) => e.semantic_type !== "observation")
	.map((e) => idMap.get(Number(e.id))!);
const signalIds = prodEvents
	.filter((e) => e.semantic_type === "observation")
	.map((e) => idMap.get(Number(e.id))!);

// BEFORE: signal interleaved with its source, exactly as the old script built it.
const beforeIds: number[] = [];
for (let i = 0; i < signalIds.length; i++) {
	if (sourceIds[i] !== undefined) beforeIds.push(sourceIds[i]!);
	beforeIds.push(signalIds[i]!);
}

const body = prodEvents
	.filter((e) => e.semantic_type === "observation")
	.map(
		(e) =>
			`[${e.metadata?.priority ?? "normal"}] ${e.metadata?.author ?? "Someone"} (${e.metadata?.platform ?? "social"}) — ${e.metadata?.why ?? "New signal"}`,
	)
	.join("\n");

async function emit(label: string, ids: number[], minutesAgo: number) {
	const [ev] = await sql`
    INSERT INTO events
      (organization_id, origin_id, title, payload_type, payload_text,
       occurred_at, metadata, semantic_type, origin_type, run_id, created_by, entity_ids)
    VALUES
      (${orgId}, ${`localseed:notification:${label}`},
       ${`Social interest radar (${label} fix)`}, 'text', ${body},
       now() - (${minutesAgo} || ' minutes')::interval,
       ${sql.json({
					notification_type: "agent_message",
					resource_url: `/${ORG_SLUG}/memory?content_ids=${ids.join(",")}`,
					behavior_id: Number(beh.id),
				})},
       'notification', 'observation', ${run.id}, ${USER_ID}, '{}')
    RETURNING id`;
	await sql`
    INSERT INTO notification_targets (event_id, user_id, delivered_at, read_at)
    VALUES (${ev.id}, ${USER_ID}, now() - (${minutesAgo} || ' minutes')::interval, NULL)`;
	return { eventId: Number(ev.id), count: ids.length };
}

const before = await emit("BEFORE", beforeIds, 6);
const after = await emit("AFTER", signalIds, 3);

console.log("org:", orgId, "behavior:", beh.id, "run:", run.id);
console.log("source events (empty titles):", sourceIds.join(","));
console.log("signal events (titled)      :", signalIds.join(","));
console.log(`BEFORE notification ${before.eventId} → ${before.count} content_ids (interleaved)`);
console.log(`AFTER  notification ${after.eventId} → ${after.count} content_ids (signals only)`);
await sql.end();

