export default async (ctx, client) => {
  const CHROME = 479;
  const read = async (label, url) => {
    const nav = await client.operations.execute({
      connection_id: CHROME, operation_key: "navigate",
      input: { url, open_in_new_tab: true, wait_for_load: true },
    });
    const tab = nav.output?.tab_id;
    if (!tab) return { label, error: nav.error_message };
    await ctx.sleep(5000);
    const probe = await client.operations.execute({
      connection_id: CHROME, operation_key: "evaluate",
      input: { tab_id: tab, await_promise: false,
        expression: `(() => {
          const t = document.body.innerText;
          const i = t.indexOf("Showing knowledge item");
          return JSON.stringify(t.slice(i, i + 900));
        })()` },
    });
    return { label, tab, text: probe.output?.value };
  };
  const after  = await read("AFTER (signals only)",  "http://127.0.0.1:9359/burak-emre-kabakci/memory?content_ids=16,17,18,19,20");
  const before = await read("BEFORE (interleaved)", "http://127.0.0.1:9359/burak-emre-kabakci/memory?content_ids=11,16,12,17,13,18,14,19,15,20");
  return { after, before };
};

