it("round-trips produced_by and keeps it distinct from analyzed-by", () => {
	// `behavior` and `produced_by` are opposite directions over the same id:
	// events the Behavior READ vs the ones it WROTE. The Behavior page linked
	// to `?behavior=71` and got 2,289 analyzed events where 354 produced ones
	// were meant, so the two must never collapse onto one key or one param.
	const search = serializeEventFiltersToSearch({
		producedByBehaviorId: 71,
	});
	expect(search.produced_by).toBe("71");
	expect(search.behavior).toBeUndefined();
	expect(EVENT_FILTER_KEYS).toContain("produced_by");

	const parsed = parseEventFiltersFromUrl(
		new URLSearchParams(
			Object.entries(search).filter(
				(entry): entry is [string, string] => entry[1] !== undefined,
			),
		),
	);
	expect(parsed.producedByBehaviorId).toBe(71);
	expect(parsed.behaviorId).toBeUndefined();

	const params = convertFiltersToApiParams({ producedByBehaviorId: 71 });
	expect(params.produced_by_behavior_id).toBe(71);
	expect(params).not.toHaveProperty("analyzed_by_behavior_id");
});

