import { render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

const feedProps: Array<Record<string, unknown>> = [];

vi.mock("@/components/entity-tabs/events-tab/events-feed", () => ({
	EventsFeed: (props: Record<string, unknown>) => {
		feedProps.push(props);
		return <div data-testid="events-feed" />;
	},
}));

const workspaceState = {
	data: undefined as { workspace?: { type: string; id: string } } | undefined,
	isLoading: false,
};

vi.mock("@/lib/api", () => ({
	useWorkspaceRoot: () => workspaceState,
}));

import { MemoryEventsPeek } from "./memory-events-peek";

describe("MemoryEventsPeek", () => {
	beforeEach(() => {
		feedProps.length = 0;
		workspaceState.isLoading = false;
		workspaceState.data = {
			workspace: { type: "organization", id: "org-1" },
		};
	});

	it("renders the shared EventsFeed rather than its own list", () => {
		// The point of the extraction: the peek used to hand-roll a list around
		// the same query, which silently dropped supersede folding and thread
		// replies. Delegating is what keeps the card here identical to Memory's.
		render(<MemoryEventsPeek owner="acme" runId={7} />);

		expect(screen.getByTestId("events-feed")).toBeTruthy();
		expect(feedProps).toHaveLength(1);
		expect(feedProps[0]?.organizationId).toBe("org-1");
		expect(feedProps[0]?.dense).toBe(true);
		expect(feedProps[0]?.filters).toEqual({ runIds: [7] });
	});

	it("passes runIds and contentIds through together", () => {
		render(
			<MemoryEventsPeek owner="acme" runIds={[3, 4]} contentIds={[11]} />,
		);

		expect(feedProps[0]?.filters).toEqual({
			runIds: [3, 4],
			contentIds: [11],
		});
	});

	it("refuses to render a feed at all when no ids scope it", () => {
		// An unscoped peek would turn a detail pane into a full history request
		// against `events`. Better to say nothing than to fetch everything.
		render(<MemoryEventsPeek owner="acme" />);

		expect(screen.queryByTestId("events-feed")).toBeNull();
		expect(feedProps).toHaveLength(0);
		expect(screen.getByText("Nothing to preview.")).toBeTruthy();
	});

	it("stops instead of spinning when the workspace is not an organization", () => {
		workspaceState.data = { workspace: { type: "user", id: "u-1" } };

		render(<MemoryEventsPeek owner="acme" runId={7} />);

		expect(screen.queryByTestId("events-feed")).toBeNull();
		expect(screen.getByText("Couldn't resolve this workspace.")).toBeTruthy();
	});
});

