		entityIds: [],
		organizationId: orgId,
		originId: `behavior:${producerId}:output:prior-period:${Date.now()}`,
		title: "Output from an earlier period",
		content: "Output from an earlier period",
		semanticType: "observation",
		occurredAt: new Date(
			new Date(dispatched.window_start).getTime() + 60_000,
		),
		behaviorId: producerId,
	});

	// Precondition: the row really is inside the window being dispatched, so a
	// pass means the predicate excluded it rather than the window missing it.
	expect(
		new Date(priorPeriodOutput.occurred_at as string).getTime(),
