export default async (ctx, client) => {
  const conns = await client.connections.list();
  return conns.filter(c => (c.connector_key || '').includes('chrome') || (c.slug || '').includes('chrome'))
    .map(c => ({ id: c.id, slug: c.slug, connector_key: c.connector_key, status: c.status }));
}

export default async (ctx, client) => {
  const r = await client.connections.list();
  const rows = Array.isArray(r) ? r : (r.data ?? r.items ?? r.connections ?? []);
  return rows.map(c => ({ id: c.id, slug: c.slug, connector_key: c.connector_key, status: c.status }));
}

export default async (ctx, client) => {
  const out = {};
  for (const id of [479, 432]) {
    try {
      const r = await client.operations.listAvailable({ connection_id: id });
      out[id] = { readiness: r.readiness ?? r?.execution_targets, keys: (r.operations ?? []).map(o => o.operation_key ?? o.key).slice(0, 20) };
    } catch (e) { out[id] = { error: String(e && e.message || e) }; }
  }
  return out;
}

export default async (ctx, client) => {
  const CHROME = 479;
  const nav = await client.operations.execute({
    connection_id: CHROME, operation_key: "navigate",
    input: { url: "http://127.0.0.1:9362/burak-emre-kabakci/behaviors/8?view=activity", open_in_new_tab: true, wait_for_load: true },
  });
  const tab = nav.output?.tab_id ?? nav.tab_id;
  const ev = await client.operations.execute({
    connection_id: CHROME, operation_key: "evaluate",
    input: { tab_id: tab, expression: "JSON.stringify({url: location.href, title: document.title, len: document.body.innerText.length, head: document.body.innerText.slice(0,600)})", await_promise: false },
  });
  return { tab, result: ev.output ?? ev };
}

export default async (ctx, client) => {
