    input: { tab_id: 558579050, expression: "JSON.stringify(Array.from(document.querySelectorAll('a')).map(a=>({t:a.innerText.trim().slice(0,40),h:a.getAttribute('href')})).filter(x=>x.h&&(x.h.includes('memory')||x.h.includes('produced')||x.h.includes('behavior='))))", await_promise: false },
  });
