export default async (ctx, client) => {
  const CHROME = 479, tab = 558579050;
  const out = {};
  for (const [label, url] of [["produced_by", "http://127.0.0.1:9362/burak-emre-kabakci/memory?produced_by=8"], ["behavior(analyzed)", "http://127.0.0.1:9362/burak-emre-kabakci/memory?behavior=8"]]) {
    await client.operations.execute({ connection_id: CHROME, operation_key: "navigate", input: { tab_id: tab, url, wait_for_load: true } });
    await ctx.sleep(3500);
    const ev = await client.operations.execute({
      connection_id: CHROME, operation_key: "evaluate",
      input: { tab_id: tab, expression: "document.body.innerText.slice(0,1400)", await_promise: false },
    });
    out[label] = ev.output?.value ?? ev.output;
  }
  return out;
}

