258	 * lifted only when the caller explicitly asks for a future window — an `until`
259	 * past now or an `after` cursor past now. NULL occurred_at rows are kept: they
260	 * are real activity whose source timestamp was never recorded, and the
261	 * COALESCE(occurred_at, created_at) ordering ranks them by record time instead
262	 * of pinning the top.
263	 *
264	 * The returned fragment carries a leading `AND` for appending to a WHERE body;
265	 * callers building a `conditions` array strip it (see fetchClassificationStats).
266	 */
267	export function buildFutureOccurredAtClause(
268	  untilDate: Date | null,
269	  cursor: DateCursor | null
270	): { sql: string } {
271	  const nowMs = Date.now();
272	  const asksForFuture =
273	    (untilDate != null && untilDate.getTime() > nowMs) ||
274	    (cursor?.direction === 'after' &&
275	      new Date(cursor.occurredAtIso).getTime() > nowMs);
276	  if (asksForFuture) return { sql: '' };
277	  return { sql: 'AND (f.occurred_at IS NULL OR f.occurred_at <= now())' };
278	}
