function pickBehaviorScope(search: Record<string, unknown>): string | undefined {
	const raw = search.behavior;
	if (typeof raw === "number") return String(raw);
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

/** The `?behavior=<id>` drill-down under an agent scope, if any. */
export function parseBehaviorScope(
	search: Record<string, unknown>,
): string | undefined {
	return pickBehaviorScope(search);
}

