          <h2 class="case-title">{c["title"]}</h2>
        </div>
        <div class="pair">
          <figure class="panel panel--before">
            <figcaption class="panel-head"><span class="tag">before</span>
              <span class="mono case-url">{FACTS[3][1]}</span></figcaption>
